let activeFilter="All",search="",listMode=false,currentTool=null,currentView="home",focusInterval=null,stopwatchState={start:0,elapsed:0,running:false,laps:[]};
const cats=[["Image","▧","Image tools"],["Text","¶","Text tools"],["Developer","⌘","Developer tools"],["Numbers","％","Number tools"],["Generators","✳","Generators"],["Productivity","◷","Productivity"]];
function toast(msg,kind="success"){const el=document.createElement("div");el.className="toast "+kind;el.textContent=msg;$("#toastRegion").append(el);setTimeout(()=>el.remove(),2600)}
function save(key,val){try{localStorage.setItem("vexakit_"+key,JSON.stringify(val))}catch(e){}}
function load(key,def){try{return JSON.parse(localStorage.getItem("vexakit_"+key))??def}catch(e){return def}}
function favs(){return load("favorites",[])}
function recent(){return load("recent",[])}
function addRecent(id){let a=[id,...recent().filter(x=>x!==id)].slice(0,8);save("recent",a)}
function iconMarkup(t){return `<span class="tool-symbol" style="--tone:${t.tone};--tint:${t.tint}">${t.icon}</span>`}
function renderCats(){$("#categoryNav").innerHTML=cats.map(c=>`<button class="nav-item" data-cat="${c[0]}"><span class="cat-emoji">${c[1]}</span>${c[2]}</button>`).join("");$$("[data-cat]").forEach(b=>b.onclick=()=>{activeFilter=b.dataset.cat;search="";$("#mainSearch").value="";setView("home");renderTools();$("#sidebar").classList.remove("open")})}
function filtered(){let arr=tools.filter(t=>(activeFilter==="All"||t.cat===activeFilter)&&(`${t.name} ${t.desc} ${t.cat}`).toLowerCase().includes(search.toLowerCase()));return arr}
function card(t){let isFav=favs().includes(t.id);return `<article class="tool-card" data-id="${t.id}" style="--tone:${t.tone}"><div class="tool-card-top">${iconMarkup(t)}<button class="fav-mini ${isFav?"on":""}" data-fav="${t.id}" aria-label="Favorite">${isFav?"♥":"♡"}</button></div><h3>${t.name}</h3><p>${t.desc}</p><span class="card-arrow">↗</span></article>`}
function renderTools(){let arr=filtered();$("#toolsGrid").innerHTML=arr.map(card).join("");$("#toolsGrid").classList.toggle("list-view",listMode);$("#resultCount").textContent=`${arr.length} ${arr.length===1?"tool":"tools"}`;$("#emptyState").hidden=arr.length!==0;$("#toolsGrid").hidden=arr.length===0;$("#listTitle").innerHTML=(activeFilter==="All"?"Explore all tools":`Explore ${activeFilter.toLowerCase()} tools`)+`<span>.</span>`;$("#filterRow").querySelectorAll(".filter-chip").forEach(b=>b.classList.toggle("selected",b.dataset.filter===activeFilter));$$("[data-cat]").forEach(b=>b.classList.toggle("active",currentView==="home"&&b.dataset.cat===activeFilter));$$(".tool-card").forEach(el=>el.onclick=e=>{if(e.target.closest("[data-fav]"))return;navigateTool(el.dataset.id)});$$("[data-fav]").forEach(b=>b.onclick=e=>{e.stopPropagation();toggleFav(b.dataset.fav)})}
function renderFeatured(){let ids=["compress","qr","password"];$("#featuredGrid").innerHTML=ids.map(id=>{let t=tools.find(x=>x.id===id);return `<article class="featured-card" data-open="${id}" style="--tone:${t.tone};--tint:${t.tint};--glow:${t.tone}"><div class="featured-top">${iconMarkup(t)}<span class="featured-arrow">↗</span></div><h3>${t.name}</h3><p>${t.desc}</p><div class="featured-tag">${t.tag||t.cat.toUpperCase()}</div></article>`}).join("");$$("[data-open]").forEach(el=>el.onclick=()=>navigateTool(el.dataset.open))}
function setView(v){currentView=v;$$(".nav-item[data-view]").forEach(b=>b.classList.toggle("active",b.dataset.view===v));$$("[data-cat]").forEach(b=>b.classList.toggle("active",v==="home"&&b.dataset.cat===activeFilter));if(v==="favorites"){activeFilter="All";search="";let ids=favs();$("#toolsGrid").innerHTML=tools.filter(t=>ids.includes(t.id)).map(card).join("");$("#listTitle").innerHTML="Your favorites<span>.</span>";$("#resultCount").textContent=`${ids.length} saved`;$("#toolsGrid").hidden=ids.length===0;$("#emptyState").hidden=ids.length!==0;$("#featuredSection").style.display="none";$("#filterRow").style.display="none";$("#mainSearch").value="";bindCards();$("#crumbCurrent").textContent="Favorites";return}if(v==="recent"){let ids=recent();$("#toolsGrid").innerHTML=ids.map(id=>tools.find(t=>t.id===id)).filter(Boolean).map(card).join("");$("#listTitle").innerHTML="Recently used<span>.</span>";$("#resultCount").textContent=`${ids.length} recent`;$("#toolsGrid").hidden=ids.length===0;$("#emptyState").hidden=ids.length!==0;$("#featuredSection").style.display="none";$("#filterRow").style.display="none";$("#mainSearch").value="";bindCards();$("#crumbCurrent").textContent="Recently used";return}$("#featuredSection").style.display="";$("#filterRow").style.display="";$("#crumbCurrent").textContent=activeFilter==="All"?"Overview":activeFilter;renderTools()}
function bindCards(){$$(".tool-card").forEach(el=>el.onclick=e=>{if(e.target.closest("[data-fav]"))return;navigateTool(el.dataset.id)});$$("[data-fav]").forEach(b=>b.onclick=e=>{e.stopPropagation();toggleFav(b.dataset.fav)})}
function toggleFav(id){let a=favs();a=a.includes(id)?a.filter(x=>x!==id):[id,...a];save("favorites",a);if(currentTool?.id===id)$("#favoriteTool").textContent=a.includes(id)?"♥":"♡";if(currentView==="favorites")setView("favorites");else if(currentView==="recent")setView("recent");else renderTools();toast(a.includes(id)?"Added to favorites":"Removed from favorites")}
function field(label,id,placeholder="",type="text",value=""){return `<div class="field"><label for="${id}">${label}</label><input id="${id}" type="${type}" placeholder="${placeholder}" value="${value}"></div>`}
function area(label,id,placeholder="Paste or type here..."){return `<div class="field"><label for="${id}">${label}</label><textarea id="${id}" placeholder="${placeholder}"></textarea></div>`}
function button(label,id="run",cls="btn-primary"){return `<button class="btn ${cls}" id="${id}">${label}</button>`}
function result(){return `<div class="result-label">RESULT</div><div class="result-box" id="resultBox">Your result will appear here.</div>`}

