function renderToolGuide(id){
 const g=toolGuides[id]||["Use this browser-based tool to complete the task shown above.","Enter or select the information requested by the tool.","Choose the action button to process your input.","Review the result shown in the workspace.","Copy or download the result if an export option is available."];
 const title=currentTool?.name||"this tool";
 const guide=document.getElementById("toolGuide");
 guide.innerHTML=`<div class="guide-heading"><div><span class="guide-kicker">VEXAKIT FIELD GUIDE</span><h3>How to use ${escapeHtml(title)}</h3><p>Quick explanation and practical steps to get the best result.</p></div><span class="guide-badge">✦ STEP-BY-STEP</span></div><div class="guide-summary"><span class="guide-summary-icon">✧</span><p>${escapeHtml(g[0])}</p></div><ol class="guide-steps">${g.slice(1).map((step,i)=>`<li><span>${String(i+1).padStart(2,"0")}</span><p>${escapeHtml(step)}</p></li>`).join("")}</ol><div class="guide-tip"><b>GOOD TO KNOW</b><p>VexaKit processes this task in your browser where possible. Keep a copy of important original files before making changes.</p></div>`;
}

